// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.transfer;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class TransferDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"), false);
        Account priya  = new Account("CUR3001", "Priya",  new BigDecimal("250000"),  false);
        TransferService service = new TransferService();

        BigDecimal rentAmount = new BigDecimal("50000");

        // Valid transfer: caught block handles any BankException uniformly.
        try {
            service.transfer(rajesh, priya, rentAmount);
        } catch (BankException e) {
            log.severe(() -> "Transfer rejected: " + e.getMessage());
        }

        // Invalid transfer: Priya tries to send more than she holds.
        try {
            service.transfer(priya, rajesh, new BigDecimal("999999"));
        } catch (InsufficientFundsException e) {
            // Specific catch can read structured fields.
            log.severe(() -> "INSUFFICIENT on " + e.getAccountId()
                    + ": wanted " + e.getRequested() + " had " + e.getAvailable());
        } catch (BankException e) {
            log.severe(() -> "Other bank error: " + e.getMessage());
        }
    }
}

// ─── Would be in BankException.java in a real project ───
// Base CHECKED exception for the whole banking domain.
class BankException extends Exception {
    BankException(String message) { super(message); }
    BankException(String message, Throwable cause) { super(message, cause); } // preserve cause
}

// ─── Would be in InsufficientFundsException.java ───
class InsufficientFundsException extends BankException {
    private final String accountId;
    private final BigDecimal requested;
    private final BigDecimal available;

    InsufficientFundsException(String accountId, BigDecimal requested, BigDecimal available) {
        super("Insufficient funds in " + accountId + ": requested " + requested + ", available " + available);
        this.accountId = accountId;
        this.requested = requested;
        this.available = available;
    }
    String getAccountId() { return accountId; }
    BigDecimal getRequested() { return requested; }
    BigDecimal getAvailable() { return available; }
}

// ─── Would be in AccountFrozenException.java ───
class AccountFrozenException extends BankException {
    AccountFrozenException(String accountId) {
        super("Account " + accountId + " is frozen and cannot transact");
    }
}

// ─── Would be in Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;
    private final boolean frozen;

    Account(String accountId, String holderName, BigDecimal balance, boolean frozen) {
        this.accountId = accountId; this.holderName = holderName;
        this.balance = balance; this.frozen = frozen;
    }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    boolean isFrozen() { return frozen; }
}

// ─── Would be in TransferService.java ───
class TransferService {
    private static final Logger log = Logger.getLogger("BankLog");

    // Declares the checked exception so callers MUST handle it.
    void transfer(Account from, Account to, BigDecimal amount) throws BankException {
        if (from.isFrozen()) throw new AccountFrozenException(from.getAccountId());
        if (from.getBalance().compareTo(amount) < 0) {
            throw new InsufficientFundsException(from.getAccountId(), amount, from.getBalance());
        }
        from.debit(amount);
        to.credit(amount);
        log.info(() -> "Transferred Rs." + amount + " " + from.getHolderName()
                + " → " + to.getHolderName());
    }
}
